"""Verify the enumerative identity: the number of injective assignments
of m demands into k resources equals the falling factorial k(k-1)...(k-m+1),
cross-checked against a brute-force count and against k!/(k-m)!."""
from __future__ import annotations
from itertools import product
from math import factorial, prod


def partition_fn(k: int, m: int) -> int:
    """Falling factorial k^{underline m}; equals 0 when m > k."""
    return prod(k - i for i in range(m)) if m else 1


def count_injections_bruteforce(k: int, m: int) -> int:
    return sum(1 for a in product(range(k), repeat=m) if len(set(a)) == m)


def falling_via_factorials(k: int, m: int) -> int:
    return factorial(k) // factorial(k - m) if m <= k else 0


def main() -> None:
    print(f"{'k':>3}{'m':>3}{'formula':>10}{'k!/(k-m)!':>12}{'bruteforce':>12}")
    for k in range(6):
        for m in range(k + 3):
            pf, ff, bf = (partition_fn(k, m),
                          falling_via_factorials(k, m),
                          count_injections_bruteforce(k, m))
            assert pf == ff == bf
            print(f"{k:>3}{m:>3}{pf:>10}{ff:>12}{bf:>12}")
    print("All three counts agree for every (k, m).")


if __name__ == "__main__":
    main()

"""Exhibit the sharp threshold as a sign change of the order parameter.
The partition function Z(k,m) is strictly positive iff m <= k and identically
zero iff m > k, so its sign locates the transition exactly at the balance
point m = k. Also confirms monotone down-closure of satisfiability."""
from __future__ import annotations
from math import prod


def partition_fn(k: int, m: int) -> int:
    return prod(k - i for i in range(m)) if m else 1


def is_satisfiable(k: int, m: int) -> bool:
    return partition_fn(k, m) > 0


def main() -> None:
    for k in (3, 4, 5):
        print(f"k = {k} resources:")
        for m in range(k + 3):
            z = partition_fn(k, m)
            tag = "  <-- balance point (Z = k!)" if m == k else (
                  "  (collapsed to 0)" if m > k else "")
            print(f"   m={m:>2}: Z={z:>7}  satisfiable={is_satisfiable(k, m)}{tag}")
        # monotone down-closure: satisfiable at m implies satisfiable below m
        for m in range(k + 3):
            if is_satisfiable(k, m):
                assert all(is_satisfiable(k, mp) for mp in range(m + 1))
        print("   monotone down-closure verified.\n")


if __name__ == "__main__":
    main()

