function PARTITION_FN(k, m):
    result <- 1
    for i from 0 to m-1:
        factor <- k - i
        if factor <= 0:
            return 0            # a demand exceeds remaining resources
        result <- result * factor
    return result

function IS_SATISFIABLE(k, m):
    return m <= k               # O(1) sharp threshold

function CONSTRUCT_WITNESS(k, m):
    if m > k: return NONE
    return [0, 1, ..., m-1]         # identity injection

function CYCLIC_LATIN_SQUARE(N):
    L <- N x N array
    for i from 0 to N-1:
        for j from 0 to N-1:
            L[i][j] <- (i + j) mod N
    return L

