from __future__ import annotations
from typing import Optional


def construct_witness(k: int, m: int) -> Optional[list[int]]:
    """Return an injective assignment of m demands into {0,...,k-1}, or None.

    Uses the identity injection i -> i, valid precisely when m <= k. O(m).
    """
    if m > k:
        return None
    return list(range(m))


def cyclic_latin_square(n_mod: int) -> list[list[int]]:
    """Full Latin square L(i,j) = (i + j) mod N solving all rows and columns."""
    return [[(i + j) % n_mod for j in range(n_mod)] for i in range(n_mod)]

