function CYCLIC_VIOLATES_SOME_BOX(n):
    N <- n * n
    for box_row from 0 to n-1:
        for box_col from 0 to n-1:
            cells <- { (box_row*n + r, box_col*n + c) : 0<=r,c<n }
            vals  <- { (i + j) mod N : (i,j) in cells }
            if vals has a repeat:
                return TRUE
    return FALSE

