from __future__ import annotations


def cyclic(n_mod: int, i: int, j: int) -> int:
    return (i + j) % n_mod


def box_cells(n: int, box_row: int, box_col: int) -> list[tuple[int, int]]:
    """Cells of one n-by-n box in an order-n Sudoku (side N = n^2)."""
    return [(box_row * n + r, box_col * n + c)
            for r in range(n) for c in range(n)]


def box_is_all_different(n: int, box_row: int, box_col: int,
                         assign) -> bool:
    """Check a single box constraint of an order-n grid under `assign(i,j)`."""
    vals = [assign(i, j) for (i, j) in box_cells(n, box_row, box_col)]
    return len(set(vals)) == len(vals)


def cyclic_violates_some_box(n: int) -> bool:
    """True iff the cyclic square fails at least one box of the order-n grid."""
    n_mod = n * n
    assign = lambda i, j: cyclic(n_mod, i, j)
    return any(not box_is_all_different(n, br, bc, assign)
               for br in range(n) for bc in range(n))
